    """Transform a row: change 4s that are between 5s (horizontally) to 2."""
    five_indices = [c for c in range(len(row)) if row[c] == 5]

    result = row[:]
    for c in range(len(row)):
        if row[c] == 4:
            # Check if this 4 is strictly between two 5s
            before_5 = any(idx < c for idx in five_indices)
            after_5 = any(idx > c for idx in five_indices)
            if before_5 and after_5:
                result[c] = 2

    return result

