        outside_bg.add((h-1, c))
    for r in range(h):
        queue.append((r, 0))
        outside_bg.add((r, 0))
    for r in range(h):
        queue.append((r, w-1))
        outside_bg.add((r, w-1))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in outside_bg and grid[nr][nc] == background_val:
                    outside_bg.add((nr, nc))
                    queue.append((nr, nc))

    # Enclosed cells: background cells NOT in outside set
    enclosed_bg = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background_val and (r, c) not in outside_bg:
                enclosed_bg.append((r, c))

    return enclosed_bg

