def predict_output_v_final(grid):
    """
    Final prediction rule based on analysis of Demo 3:

    Rule A - Frame Row: Has exactly 2 markers AND starts with marker AND ends with marker
        → NO CHANGE

    Rule B - Single-Marker Between Anchors: Has exactly 1 marker AND is between 2+ marker rows
        → Set opposite column to target color (2)
        - If marker is at right end, set col 0 to 2
        - If marker is at left end, set last col to 2

    Rule C - Multi-Marker Row: Has ≥2 markers but NOT a frame row
        → Fill background cells between consecutive markers
        → Also handle end segment if marker doesn't reach edge
    """
    h, w = len(grid), len(grid[0])
    marker_value = 4
    bg_value = 1

    result = []
    for r in range(h):
        row = list(grid[r])
        marker_cols = [c for c in range(w) if row[c] == marker_value]
        n_markers = len(marker_cols)

        if n_markers == 0:
            pass

        elif n_markers == 2:
            start_marker = row[0] == marker_value
            end_marker = row[-1] == marker_value

            if start_marker and end_marker:
                # Frame row - no change
                pass
            else:
                # Regular pair - fill between
                for c in range(marker_cols[0] + 1, marker_cols[1]):
                    if row[c] == bg_value:
                        row[c] = 2

                # Handle end segment if exists
                if marker_cols[1] < w - 1:
                    end_segment = list(range(marker_cols[1] + 1, w))
                    for c in end_segment:
                        if row[c] == bg_value:
                            row[c] = 2

        elif n_markers >= 2:
            # Multi-marker row - fill between all consecutive pairs
            for i in range(len(marker_cols) - 1):
                start_pos = marker_cols[i]
                end_pos = marker_cols[i + 1]
                for c in range(start_pos + 1, end_pos):
                    if row[c] == bg_value:
                        row[c] = 2

            # Handle end segment
            if marker_cols[-1] < w - 1:
                end_segment = list(range(marker_cols[-1] + 1, w))
                for c in end_segment:
                    if row[c] == bg_value:
                        row[c] = 2

        elif n_markers == 1:
            # Single marker row
            pos = marker_cols[0]
            marker_at_start = pos == 0
            marker_at_end = pos == w - 1

            # Check if between anchor rows (simple heuristic)
            num_rows_with_markers = sum(1 for rr in range(h) 
                                       if any(grid[rr][cc] == marker_value for cc in range(w)))
            is_between = (num_rows_with_markers > 3)

            if is_between:
                if marker_at_start:
                    row[w - 1] = 2
                elif marker_at_end:
                    row[0] = 2

        result.append(row)

    return result

